1	#!/usr/bin/env node
2	// The sheepdog pack's FORCE-BASELINE sweep — the enforcer's one manual lever over the
3	// whole fleet. Run by the pack's `fleet-baseline` workflow (stubs/workflows/fleet-baseline.yml,
4	// vendored into the enforcer repo's own .github/ by the `sheepdog-fleet-baseline` migration),
5	// on `workflow_dispatch` only. Still runnable by hand (`node force-fleet-baseline.mjs`) via
6	// the CLI guard at the foot.
7	//
8	// WHAT IT DOES. Enumerate every covered member under the configured owner and, for each,
9	// fire ITS OWN scheduler workflow with `overrides: FORCE_TASKS=baselining` — the same
10	// manual-run lever the owner would pull by hand in that repo's Actions tab, pulled across
11	// the fleet in one run. Nothing here re-implements baselining: each member converges its
12	// own mount, with its own token, under its own scheduler and its own delivery policy. This
13	// sweep only presses the button, which is why it is a dispatcher and not a maintainer.
14	//
15	// WHY IT EXISTS. Under per-project scheduling every member baselines itself hourly, so the
16	// fleet needs no push in the ordinary case. The cases it is FOR are the un-ordinary ones:
17	// a canon change the fleet should pick up now rather than over the next day (a broken
18	// vendored file, a migration record that must land before something else), and the tail of
19	// members whose next slot is hours away when someone is standing by to watch the result.
20	// A forced run bypasses baselining's precondition (the engine records it as forced and says
21	// the precondition was never evaluated), so a member with nothing to do converges to a
22	// cheap no-op — the sweep is safe to over-use, only wasteful.
23	//
24	// WHY IT IS A WORKFLOW AND NOT A TASK. Every other thing this pack does is a scheduled
25	// task, because it answers a recurring question. This answers no question and has no
26	// cadence: it is an OWNER-INITIATED operation with its own inputs (a repo filter, a dry
27	// run), and the thing that starts it is a human pressing "Run workflow". It carries no
28	// `schedule:` trigger, so the doctrine it would otherwise break — a repo's vendored
29	// scheduler is its ONLY cron (packs/basics/scheduled-tasks.md) — is untouched.
30	//
31	// THE TOKEN. FLEET_GITHUB_TOKEN, the same account-spanning PAT the three sweeps use, plus
32	// ONE scope they do not need: **Actions: read and write** on the owner's repositories.
33	// Dispatching another repo's workflow is a write to that repo's Actions, and a PAT scoped
34	// only for the sweeps gets a 403 here. That 403 is reported per repo and fails the run
35	// rather than being retried, because it is a grant to fix once, not a transient.
36	//
37	// Dependency-free (global fetch, Node 20+). It writes NOTHING to any member — no commit,
38	// no issue, no comment; the single side effect per member is one queued Actions run.
39	//
40	// It lives in its own folder under the pack root, beside the tasks rather than inside one,
41	// because it belongs to no task — its runner is the vendored workflow. What it shares with
42	// the sweeps stays where it was: the REST primitives (fleet-api.mjs) and the config reader
43	// (fleet-config.mjs), both one level up.
44	
45	import { appendFileSync } from 'node:fs';
46	import { pathToFileURL } from 'node:url';
47	import { makeGh, paged, readDeclaration, isDormant, DECLARATION } from '../fleet-api.mjs';
48	import { parseSheepdogConfig } from '../fleet-config.mjs';
49	
50	// The member-side workflow being fired, and the exact manual-run override it is fired
51	// with. Both are the vendored scheduler's public surface (engine/scheduler/stubs/
52	// claudinite-scheduler.yml + `forcedTaskIds` in engine/scheduler/run.mjs); named here as
53	// constants so the coupling is one line to find, not a string buried in a request body.
54	export const SCHEDULER = 'claudinite-scheduler.yml';
55	export const FORCE_OVERRIDES = 'FORCE_TASKS=baselining';
56	
57	// --- classification (pure) ----------------------------------------------------
58	
59	// What the dispatch POST's status means. Every branch is a DIFFERENT thing for the
60	// reader to do, which is why the sweep reports a state per repo instead of a count of
61	// failures: a 404 is a repo to adopt, a 403 is a token to re-scope, a 422 is a workflow
62	// GitHub has switched off. Kept free of I/O so the whole table is testable directly.
63	export function classifyDispatch(status) {
64	  switch (status) {
65	    case 204:
66	      return { state: 'forced', detail: 'baselining queued on its own scheduler' };
67	    case 404:
68	      // The workflow is missing, the repo has Actions disabled, or the PAT cannot see the
69	      // repo at all — indistinguishable from here, and all three mean "nothing was queued".
70	      return { state: 'no-scheduler', detail: `no ${SCHEDULER} on the default branch, or Actions is disabled — nothing there can baseline itself` };
71	    case 403:
72	      return { state: 'no-permission', detail: 'the PAT lacks Actions: write on this repo — dispatching a workflow is an Actions write, a scope the read-only sweeps never needed' };
73	    case 422:
74	      // GitHub disables a repo's scheduled workflows after 60 days of inactivity, and a
75	      // disabled workflow refuses dispatch; a scheduler stub too old to carry the
76	      // `overrides` input lands here too.
77	      return { state: 'not-dispatchable', detail: 'the workflow exists but refused the dispatch — it is disabled (GitHub switches off cron on inactive repos), or too old to accept the `overrides` input' };
78	    default:
79	      return { state: 'error', detail: `dispatch returned ${status}` };
80	  }
81	}
82	
83	// The `repos` input, resolved against the owner: a comma/whitespace-separated list of
84	// bare names or full `owner/name`, lowercased, or null for "every member". A bare name is
85	// qualified with the configured owner, because that is the only owner this sweep can
86	// reach and typing it twenty times is friction with no upside.
87	export function parseRepoFilter(raw, owner) {
88	  const names = String(raw ?? '').split(/[\s,]+/).map((s) => s.trim()).filter(Boolean);
89	  if (!names.length) return null;
90	  return new Set(names.map((n) => (n.includes('/') ? n : `${owner}/${n}`).toLowerCase()));
91	}
92	
93	// --- the dispatch -------------------------------------------------------------
94	
95	// Fire one member's scheduler. `ref` is the member's DEFAULT branch (read from the
96	// enumeration, never assumed to be `main`): workflow_dispatch resolves the workflow file
97	// on the ref it is given, and a repo whose trunk is `master` would otherwise 404 as if it
98	// carried no scheduler at all.
99	export async function forceOne(gh, fullName, ref) {
100	  const { status } = await gh(`/repos/${fullName}/actions/workflows/${SCHEDULER}/dispatches`, {
101	    method: 'POST',
102	    body: { ref, inputs: { overrides: FORCE_OVERRIDES } },
103	  });
104	  return classifyDispatch(status);
105	}
106	
107	// --- main ---------------------------------------------------------------------
108	
109	export async function main() {
110	  const token = process.env.FLEET_GITHUB_TOKEN;
111	  const home = process.env.GITHUB_REPOSITORY;
112	  if (!token) {
113	    throw new Error('FLEET_GITHUB_TOKEN is not set. Add a repo secret with a fine-grained PAT '
114	      + '(this account, ALL repositories, Metadata read, Contents read, and Actions READ AND WRITE) — '
115	      + 'the default GITHUB_TOKEN sees only this repo and cannot dispatch another repo\'s workflow.');
116	  }
117	  if (!home || !home.includes('/')) throw new Error('GITHUB_REPOSITORY is not set (owner/repo)');
118	  const gh = makeGh(token);
119	
120	  const dryRun = String(process.env.FLEET_BASELINE_DRY_RUN ?? '').toLowerCase() === 'true';
121	  const includeDormant = String(process.env.FLEET_BASELINE_INCLUDE_DORMANT ?? '').toLowerCase() === 'true';
122	
123	  const cfgRes = await gh(`/repos/${home}/contents/${DECLARATION}`);
124	  if (cfgRes.status !== 200 || !cfgRes.json?.content) {
125	    throw new Error(`the sheepdog repo ${home} has no readable ${DECLARATION} (status ${cfgRes.status})`);
126	  }
127	  let cfg;
128	  try { cfg = JSON.parse(Buffer.from(cfgRes.json.content, 'base64').toString('utf8')); } catch (e) {
129	    throw new Error(`unparsable ${DECLARATION} on ${home}: ${e.message}`);
130	  }
131	  const { owner, exclude, canonRepo } = parseSheepdogConfig(cfg, home);
132	  const filter = parseRepoFilter(process.env.FLEET_BASELINE_REPOS, owner);
133	
134	  const mine = (await paged(gh, '/user/repos?affiliation=owner'))
135	    .filter((r) => r.owner.login.toLowerCase() === owner);
136	  if (mine.length === 0) {
137	    throw new Error(`enumeration returned no repos owned by ${owner} — wrong token user or scope`);
138	  }
139	
140	  const forced = []; const skipped = []; const failed = [];
141	  for (const r of mine.sort((a, b) => a.name.localeCompare(b.name))) {
142	    const fullName = r.full_name.toLowerCase();
143	    // Canon has no vendored mount, so its own baselining self-skips — forcing it would
144	    // queue a run whose only outcome is that skip. The enforcer repo itself is NOT
145	    // exempt: it is an ordinary member with a mount to converge, and leaving it out of a
146	    // fleet-wide force would make the one repo the owner is looking at the one repo that
147	    // did not move.
148	    if (fullName === canonRepo.toLowerCase()) continue;
149	    if (r.archived || r.fork || exclude.has(fullName)) continue;
150	    if (filter && !filter.has(fullName)) continue;
151	
152	    let decl;
153	    try {
154	      decl = await readDeclaration(gh, r.full_name);
155	    } catch (e) {
156	      // Unreadable is not uncovered: a repo whose declaration could not be read might be
157	      // a member that needed this run, so it is a FAILURE to escalate, never a silent skip.
158	      failed.push({ fullName, state: 'error', detail: `could not read ${DECLARATION}: ${e.message}` });
159	      continue;
160	    }
161	    if (decl === null) continue;                                        // uncovered — the census's business
162	    if (isDormant(decl) && !includeDormant) {
163	      // A dormant member stopped its own scheduler; a forced dispatch on it either does
164	      // nothing (the run stops before evaluating anything) or wakes a repo that asked to
165	      // sleep. Reported, not silently dropped, so a fleet-wide force is never mistaken
166	      // for fleet-wide coverage.
167	      skipped.push({ fullName, state: 'dormant', detail: 'self-declared dormant — pass include_dormant to force it anyway' });
168	      continue;
169	    }
170	
171	    if (dryRun) {
172	      forced.push({ fullName, state: 'would-force', detail: `would dispatch ${SCHEDULER}@${r.default_branch} with ${FORCE_OVERRIDES}` });
173	      continue;
174	    }
175	    const verdict = await forceOne(gh, r.full_name, r.default_branch);
176	    if (verdict.state === 'forced') forced.push({ fullName, ...verdict });
177	    else failed.push({ fullName, ...verdict });
178	  }
179	
180	  const runsUrl = (n) => `https://github.com/${n}/actions/workflows/${SCHEDULER}`;
181	  const summary = [
182	    `# Fleet baseline — ${owner}${dryRun ? ' (DRY RUN — nothing was dispatched)' : ''}`,
183	    '',
184	    `Fired \`${FORCE_OVERRIDES}\` at each covered member's own \`${SCHEDULER}\`.`,
185	    filter ? `Filtered to: ${[...filter].join(', ')}` : '',
186	    '',
187	    `| ${dryRun ? 'would force' : 'forced'} | skipped | failed |`,
188	    '| --- | --- | --- |',
189	    `| ${forced.length} | ${skipped.length} | ${failed.length} |`,
190	    '',
191	    forced.length
192	      ? `**${dryRun ? 'Would force' : 'Forced'}:**\n${forced.map((f) => `- [\`${f.fullName}\`](${runsUrl(f.fullName)})`).join('\n')}`
193	      : '**No member was dispatched** — check the filter, or whether anything under this owner is covered.',
194	    skipped.length ? `**Skipped:**\n${skipped.map((s) => `- \`${s.fullName}\` — **${s.state}**: ${s.detail}`).join('\n')}` : '',
195	    failed.length ? `**Failed:**\n${failed.map((f) => `- \`${f.fullName}\` — **${f.state}**: ${f.detail}`).join('\n')}` : '',
196	    '',
197	    // The dispatch API returns 204 with no body, so there is no run id to link: each
198	    // member's own workflow page is the honest destination. A queued run is not a
199	    // finished baseline, and this sweep deliberately does not wait for one — a fleet's
200	    // worth of member runs takes longer than a poll loop should hold an Action open.
201	    '_A dispatch queues a run; it does not report its outcome. Each member reports its own_',
202	    '_baselining the way it always does — a maintenance PR, or a failure issue in that repo._',
203	  ].filter(Boolean).join('\n');
204	
205	  console.log(summary);
206	  if (process.env.GITHUB_STEP_SUMMARY) appendFileSync(process.env.GITHUB_STEP_SUMMARY, `${summary}\n`);
207	
208	  if (failed.length) {
209	    throw new Error(`${failed.length} member(s) could not be forced (${failed.map((f) => `${f.fullName}: ${f.state}`).join('; ')}) — `
210	      + 'the rest were dispatched, and this run fails so the cause is escalated');
211	  }
212	}
213	
214	const isMain = process.argv[1] && import.meta.url === pathToFileURL(process.argv[1]).href;
215	if (isMain) {
216	  main().catch((e) => { console.error(`fleet-baseline failed: ${e.message}`); process.exit(1); });
217	}
218

